/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: CatalogReviewLookupDetails
 * Internal
 *   Functions: ChunkUnavailable, chunk, memberPath, Results
 *   Constants: CandidateChooser, CatalogReviewIdentities
 * @end-catalog */

import { lazy, Suspense, useEffect, useId, useLayoutEffect, useRef, type ComponentProps, type ComponentType, type ReactNode } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { useAdminAccess, useAdminText } from './AdminAccess';
import { entriesByline } from './artistEntriesByline';
import type { CatalogReview } from './catalogReviewApi';
import { catalogReviewCandidatesQuery, catalogReviewKey, catalogReviewSummaryQuery } from './catalogReviewSummaryQuery';
import type { CatalogReviewIdentities as Identities } from './CatalogReviewIdentities';
import type { CandidateChooser as Chooser } from './CandidateChooser';
import { expectedRowMembers, lookupAnswers, memberRows, openLookupAnswers, type ReviewConflict } from './catalogReviewSummaryModel';
import { lookupActive, lookupNextStep } from './lookupNextStep';
import { lookupIdText, lookupValueAt, lookupValueText } from './lookupValueText';
import { reviewAppliedAgain, titleNumbers } from './reviewLookupStatus';
import { useOnline } from './useAdminOnline';
import styles from './adminStyles';

/** Stands in for a chunk of these details that cannot load (a deploy replaced it); the rest of the details and the editor stay usable. */
function ChunkUnavailable() { const t = useAdminText(); return <p role="alert">{t('common.reload')}</p>; }
/** A chunk these details load only when they show it: the candidate chooser and the identity rows. */
const chunk = <P extends object>(load: () => Promise<ComponentType<P>>) =>
  lazy<ComponentType<P>>(() => load().then(component => ({ default: component }), () => ({ default: ChunkUnavailable })));
const CandidateChooser = chunk<ComponentProps<typeof Chooser>>(() => import('./CandidateChooser').then(module => module.CandidateChooser));
const CatalogReviewIdentities = chunk<ComponentProps<typeof Identities>>(() => import('./CatalogReviewIdentities').then(module => module.CatalogReviewIdentities));
const memberPath = (path: string) => /^tracks\.[^.]+\.artists$/.test(path);
/**
 * The results' one element, which never remounts. Until a release is applied (`label` null) it is no fold: open with its summary
 * hidden, browsers expose no disclosure control or expanded state, only an unnamed group, and nothing can close it. It folds as
 * the results settle and opens as soon as they no longer are.
 */
function Results({ fold, label, children }: { fold: boolean; label: string | null; children: ReactNode }) {
  const element = useRef<HTMLDetailsElement>(null);
  useLayoutEffect(() => { element.current!.open = !fold; }, [fold]);
  return <details ref={element} style={label ? { marginTop: '.75rem' } : undefined}>{label
    ? <summary style={{ cursor: 'pointer', padding: '.3rem 0' }}>{label}</summary> : <summary style={{ display: 'none' }} />}{children}</details>;
}

/**
 * The lookup details of an existing-Album review, after the update range (design v3; owner rules: docs/business-rules.md, Catalog
 * Visibility and Administration, existing-Album reviews; Administrator Metadata Lookup). They present what the server decides and
 * never start Luna; the status line above (CatalogReviewStatus.tsx) says the lookup's status and next step, and the name box opens
 * from the page's row of alternatives (CatalogReviewLookupAnother.tsx). In order: how many optional lookup answers are open (their
 * fields stay out of this update until answered); the identity rows (`catalog-review-identities`, the update range's link), which
 * say themselves how many identity records are open, directly after the range; the results:
 * conflicts answered one by one or all at once by buttons that name the applied candidate's source (MusicBrainz or iTunes), the
 * values to check, each member's track Artist row with its reason, the expected tracklist with its missing-file rows and the values
 * that need no answer; for a release this run applied for its Album values only whose tracks still pair in more than one way while
 * the titles propose the numbers, a line saying why its tracks are not applied; the free retry (labelled free, a plain button, as
 * the action bar's update is the page's one primary), never for a run that ended because the review's source was no longer current
 * (superseded), which could not run while it is not; and the candidate chooser, one collapsed Reference releases disclosure that
 * opens only where choosing is the next step (CandidateChooser.tsx). Once a release this run applied leaves nothing open (no
 * active run, retry or lookup answer, nor the numbers line) and flags no iTunes-only value or artist mismatch, which are never
 * collapsed, the results fold under one disclosure (`Results`); it stays mounted. The section carries `catalog-review-lookup` (the
 * focus target after the chooser's pairing panel closes) and renders nothing while its read loads or when it has nothing to show.
 * A refused answer reads the summary and the identity rows again. A chunk it loads that cannot load asks for a reload in its place.
 */
export function CatalogReviewLookupDetails({ item, disabled, error, onRun }: {
  item: CatalogReview; disabled: boolean; error: string | null; onRun: (action: string, payload: object) => void;
}) {
  const t = useAdminText(), access = useAdminAccess(), online = useOnline(), client = useQueryClient(), id = useId();
  const query = useQuery(catalogReviewSummaryQuery(access, item, online)), data = query.data, lookup = data?.lookup ?? null, summary = data?.summary;
  const key = catalogReviewKey(access, item.id), applied = lookup?.applied ?? null, shown = applied && applied.choice !== 'none' ? applied : null;
  // The identity rows' own read (CatalogReviewIdentities, shown under the same condition), observed here only for their count.
  const identity = useQuery({ ...catalogReviewCandidatesQuery(access, item), enabled: Boolean(shown) && item.draft.album.expectedTracklist !== undefined && item.sourceStatus === 'current' });
  useEffect(() => {
    if (error === 'conflict' || error?.startsWith('lookup_')) for (const part of ['lookup', 'candidates']) void client.invalidateQueries({ queryKey: [...key, part] });
  }, [error]);
  const position = (slotId: string) => item.draft.tracks.findIndex(track => track.slotId === slotId) + 1;
  const member = (slotId: string) => `${position(slotId)} · ${item.draft.tracks.find(track => track.slotId === slotId)?.title || '—'}`;
  const label = (path: string) => {
    const [scope, first, field] = path.split('.');
    return scope === 'album' ? t(first === 'expectedTracklist' ? 'catalog.album_expected' : `field.${first}`) : t('summary.track_field', { position: position(first), field: t(`field.${field}`) });
  };
  // The status line says the read's loading and errors.
  if (!data || !summary) return null;
  const { status, retry } = lookupNextStep(lookup, { available: summary.lookupAvailable, uploadsWaiting: false });
  const appliedCandidate = lookup?.candidates.find(candidate => candidate.key === applied?.candidateKey);
  // The Album name the run searched (a song name never is: then the saved title) compares the titles; the captured titles over the
  // saved numbers give the numbers the review page proposes (catalogReviewProposal.ts reads them the same way).
  const submitted = lookup?.input.submitted, searched = submitted?.kind === 'album' ? submitted.text : item.draft.album.title;
  const artists = item.draft.album.artists.filter(entry => entry.role === 'primary').map(entry => entry.name);
  const numbers = titleNumbers(item.source.tracks.map(track => ({ ...item.draft.tracks.find(value => value.slotId === track.slotId)!, title: track.title })),
    new Set(item.source.tracks.filter(track => track.discNumber !== undefined).map(track => track.slotId)));
  // Only Disc and Track positions arrive selected, so only they are what a save writes; Track Numbers alone wait to be checked
  // and ticked, and the copy offers manual editing and pairing by hand for them instead.
  const proposed = numbers?.disc ? numbers.count : 0;
  // A previous revision's read shown while the current one loads takes no answer.
  const busy = disabled || query.isPlaceholderData, active = lookupActive(lookup?.state), answering = busy || active;
  const { needed, open, answers } = openLookupAnswers(lookup);
  const albumOpen = open.filter(conflict => !memberPath(conflict.path)), conflictPaths = new Set((applied?.conflicts ?? []).map(conflict => conflict.path));
  const source = applied?.source === 'itunes' ? 'iTunes' : 'MusicBrainz', use = applied?.source === 'itunes' ? 'itunes' : 'musicbrainz';
  const resolve = (conflicts: readonly ReviewConflict[], answer: 'mine' | 'lookup') =>
    onRun('lookup/resolve', { run: applied!.run, candidateKey: applied!.candidateKey, answers: lookupAnswers(conflicts, item.draft, answer) });
  const card = (conflict: ReviewConflict, heading: string) => {
    const text = conflict.musicBrainzId ? lookupIdText : lookupValueText, title = `${id}-${conflict.path}`;
    return <li key={conflict.path} className={styles.card}>
      <strong id={title}>{conflict.precision ? `${heading} · ${t('catalog_review.adds_precision')}` : heading}</strong>
      <dl className={styles.diff}><div><dt>{t('catalog_review.current_value')}</dt><dd>{text(lookupValueAt(item.draft, conflict.path))}</dd></div><div><dt>{source}</dt><dd>{text(conflict.lookup)}</dd></div></dl>
      <div className={styles.actions}>{(['mine', 'lookup'] as const).map(answer => <button key={answer} type="button" className={styles.button} disabled={answering} aria-describedby={title}
        onClick={() => resolve([conflict], answer)}>{t(answer === 'mine' ? 'catalog_review.keep_current' : `catalog_review.use_${use}`)}</button>)}</div></li>;
  };
  const conflictHeading = (conflict: ReviewConflict) => conflict.musicBrainzId ? t('summary.musicbrainz_id_conflict', { field: label(conflict.path) }) : label(conflict.path);
  const answered = (conflict: ReviewConflict) => t(conflict.answer === 'lookup' ? 'catalog_review.used_lookup' : 'catalog_review.kept_current', { source });
  const members = memberRows(lookup, item.draft);
  // Values to check: an iTunes-only application's values (never collapsed), an artist mismatch of this run's preselection, and
  // values lookup could not apply, with their reason; members show theirs in their own rows.
  const itunes = shown?.source === 'itunes' ? shown.values.map(value => value.path) : [];
  const itunesMark = [t('lookup.itunes_only'), shown?.notChecked && t('lookup.not_checked')].filter(Boolean).join(' · ');
  const mismatch = Boolean(lookup?.preselection?.artistMismatch && applied?.choice === 'preselected' && applied.run === lookup?.run);
  const flagged = (shown?.flagged ?? []).filter(flag => !memberPath(flag.path));
  // The expected tracklist of a review captured for lookup, with the members at each row: the open conflict's rows, else the
  // saved draft's, whether or not lookup applied any.
  const rowsConflict = open.find(conflict => conflict.path === 'album.expectedTracklist');
  const rows = (rowsConflict?.lookup as NonNullable<CatalogReview['draft']['album']['expectedTracklist']> | undefined) ?? item.draft.album.expectedTracklist ?? null;
  const preview = rows && item.draft.album.expectedTracklist !== undefined ? expectedRowMembers(rows, item.draft.tracks) : null;
  // A conflict answered with the lookup value is also an applied value: it folds once, as answered, unless iTunes values flag it.
  const folded = [...(shown && shown.source !== 'itunes' ? shown.values.filter(value => !memberPath(value.path) && !conflictPaths.has(value.path))
    .map(value => [value.path, lookupValueText(lookupValueAt(item.draft, value.path))]) : []),
    ...(applied?.conflicts ?? []).filter(conflict => !needed.has(conflict.path) && conflict.answer && !memberPath(conflict.path) && !itunes.includes(conflict.path))
      .map(conflict => [conflict.path, `${lookupValueText(conflict.lookup)} · ${answered(conflict)}`])];
  // A run superseded because the source was no longer current offers no retry (the server refuses it while it is not).
  const closed = lookup?.state === 'superseded';
  const section = (name: string, heading: string, body: ReactNode) => <section aria-labelledby={`${id}-${name}`}>
    <h3 id={`${id}-${name}`}>{heading}</h3>{body}</section>;
  const identityNeeded = identity.data ? identity.data.identities.filter(row => row.needsAnswer).length + (identity.data.label?.needsAnswer ? 1 : 0) : 0;
  // A release this run applied for its Album values only, whose tracks still pair in more than one way while the titles propose
  // the numbers, says so after the results: its tracks are not applied until saved numbers pair them.
  const numbersOpen = Boolean(numbers?.count && shown?.pairs === null && shown.run === lookup?.run && appliedCandidate?.comparison?.subset?.pairing === 'ambiguous');
  // iTunes-only values and an artist mismatch are flagged and never collapsed (owner rules), so they keep the results open.
  const settled = Boolean(shown) && shown!.source !== 'itunes' && !mismatch && !active && answers === 0 && !retry && !numbersOpen;
  const membersShown = Boolean(members && (!members.paired || members.rows.length > 0)), flaggedShown = itunes.length > 0 || mismatch || flagged.length > 0;
  const identities = item.draft.album.expectedTracklist !== undefined && Boolean(shown) && item.sourceStatus === 'current';
  const resultsShown = open.length >= 2 || albumOpen.length > 0 || flaggedShown || membersShown || Boolean(preview) || folded.length > 0;
  const chooser = lookup?.state === 'complete' && lookup.candidates.length > 0, retrying = retry && !closed;
  if (!answers && !identityNeeded && !identities && !resultsShown && !numbersOpen && !retrying && !chooser) return null;
  const body = <>
    {/* The bulk answers cover every open conflict, the members' included, so they also serve member conflicts alone. */}
    {open.length >= 2 && <div className={styles.actions}>
      <button type="button" className={styles.button} disabled={answering} onClick={() => resolve(open, 'mine')}>{t('catalog_review.keep_all_current')}</button>
      <button type="button" className={styles.button} disabled={answering} onClick={() => resolve(open, 'lookup')}>{t(`catalog_review.use_all_${use}`)}</button></div>}
    {albumOpen.length > 0 && section('conflicts', t('catalog_review.conflicts'), <ul className={styles.cards}>{albumOpen.map(conflict => card(conflict, conflictHeading(conflict)))}</ul>)}
    {(itunes.length > 0 || mismatch || flagged.length > 0) && <ul aria-label={t('summary.flagged')}>
      {mismatch && <li>{t('catalog_review.artist_mismatch')}</li>}
      {itunes.map(path => <li key={path}>{`${label(path)} · ${lookupValueText(lookupValueAt(item.draft, path))} · ${itunesMark}`}</li>)}
      {flagged.map(flag => <li key={flag.path}>{`${label(flag.path)} · ${t(`catalog_review.flag_${flag.reason}`)}`}</li>)}</ul>}
    {members && membersShown && section('members', t('catalog_review.members_title'), <>
      <p className={styles.muted}>{t('catalog_review.members_copy')}</p>
      {!members.paired && <p>{t(lookup && reviewAppliedAgain(lookup, status) ? 'catalog_review.member_paired_since' : 'catalog_review.member_no_pairing')}</p>}
      {members.rows.length > 0 && <ul className={styles.cards}>{members.rows.map(row => row.state === 'conflict' ? card(row.conflict, member(row.slotId))
        : <li key={row.slotId} className={styles.card}><strong>{member(row.slotId)}</strong><p>{row.state === 'filled' ? `${entriesByline(row.entries) || '—'} · ${t('catalog_review.member_filled')}`
          : row.state === 'answered' ? `${lookupValueText(row.conflict.lookup)} · ${answered(row.conflict)}`
            : t(row.reason === 'unpaired' ? 'catalog_review.member_unpaired' : `catalog_review.flag_${row.reason}`)}</p></li>)}</ul>}</>)}
    {preview && section('expected', t('catalog.album_expected'), <>
      <p>{t('catalog_review.expected_rows', { rows: preview.rows.length, noFile: preview.noFile })}</p>
      <p className={styles.muted}>{t('catalog_review.expected_copy')}</p>
      <ol>{preview.rows.map(({ row, slotIds }) => <li key={`${row.discNumber}:${row.trackNumber}`}>{[t('publication.track_position', { disc: String(row.discNumber), track: String(row.trackNumber) }),
        row.title, slotIds.length ? slotIds.map(member).join(', ') : t('catalog.album_expected_no_file')].join(' · ')}</li>)}</ol>
      {preview.outside.length > 0 && <p>{`${t('catalog.album_expected_outside')}: ${preview.outside.map(member).join(', ')}`}</p>}</>)}
    {folded.length > 0 && <details className={styles.details}><summary>{t('catalog_review.values_handled')}</summary><dl>
      {folded.map(([path, text]) => <div key={path}><dt>{label(path)}</dt><dd>{text}</dd></div>)}</dl></details>}
  </>;
  // Focusable for the candidate chooser, which returns focus here once its pairing panel closes without its opener.
  // Named without a heading of its own (design v3 shows none): its h3 sections follow the status line's heading.
  return <section id="catalog-review-lookup" aria-label={t('catalog_review.lookup_title')} className={styles.lookupDetails} tabIndex={-1}>
    {answers > 0 && <p role="status">{t('catalog_review.needs_answers', { count: answers })}</p>}
    {identities && <div id="catalog-review-identities"><Suspense fallback={null}>
      <CatalogReviewIdentities item={item} disabled={busy} onSave={decisions => onRun('decisions', { decisions })} /></Suspense></div>}
    {resultsShown && <Results fold={settled} label={shown && t('catalog_review.lookup_details')}>{body}</Results>}
    {numbersOpen && <><p>{t('catalog_review.member_no_pairing')}</p>
      <p>{t(`catalog_review.lookup_fill_${proposed ? 'hint' : 'unavailable'}${appliedCandidate!.comparison!.unknownLocalDurations ? '_durations' : ''}`, { count: proposed })}</p></>}
    {retrying && <div className={styles.actions}><button type="button" className={styles.button} disabled={busy} onClick={() => onRun('lookup/retry', {})}>{t('catalog_review.lookup_retry_free')}</button></div>}
    {chooser && lookup && <Suspense fallback={null}><CandidateChooser projectId={item.id} viewerId={access.viewerId} lookup={lookup}
      review={{ tracks: item.draft.tracks, searched, artists, numbers: proposed }} disabled={busy} onChoose={candidateKey => onRun('lookup/choose', { run: lookup.run, candidateKey })} /></Suspense>}
  </section>;
}
